rm -rf "$d"

# LOG-31: keep=3 (config/rotate.conf) prunes both local and archive generations
d=$(mktemp -d); mkdir -p "$d/logs"
for i in 1 2 3 4 5 6; do echo "g$i" > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
echo keepme > "$d/logs/other.log.9"; echo keepme > "$d/archive/other.log.20200101"
bash bin/rotate "$d/logs" "$d/archive" app.log 20261007
[ "$(ls "$d/logs" | grep -c '^app\.log\.[0-9]*$')" = 3 ] || { echo "local count"; fail=1; }
[ -e "$d/logs/app.log.4" ] && { echo "app.log.4 should be gone"; fail=1; }
[ "$(ls "$d/archive" | grep -c '^app\.log\.[0-9]\{8\}$')" = 3 ] || { echo "archive count"; fail=1; }
[ -e "$d/archive/app.log.20261007" ] || { echo "newest archive kept"; fail=1; }
[ -e "$d/archive/app.log.20261004" ] && { echo "old archive should be gone"; fail=1; }
[ -e "$d/logs/other.log.9" ] && [ -e "$d/archive/other.log.20200101" ] || { echo "other name touched"; fail=1; }
# invalid keep must not delete anything
before=$(ls "$d/archive" | wc -l); printf 'keep=0\n' > "$d/bad.conf"
ROTATE_CONF="$d/bad.conf" bash bin/rotate "$d/logs" "$d/archive" app.log 20261010 2>/dev/null && { echo "keep=0 should fail"; fail=1; }
[ "$(ls "$d/archive" | wc -l)" -ge "$before" ] || { echo "keep=0 deleted"; fail=1; }
rm -rf "$d"
exit $fail

